fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    assert!(!v.is_empty(), "array must be non-empty");

    let mut lo: usize = 0;
    let mut hi: usize = v.len() - 1;

    while lo < hi {
        // mid is always in [lo, hi)
        let mid = lo + (hi - lo) / 2;

        if v[mid] < k {
            // keep [mid + 1, hi]
            lo = mid + 1;
        } else {
            // keep [lo, mid]
            hi = mid;
        }
    }

    // lo == hi, and k is guaranteed to exist, so this must be k
    debug_assert!(lo < v.len());
    debug_assert!(v[lo] == k);
    lo
}